<?php
require_once '../config/database.php';require_once '../config/response.php';require_once '../eventos/helpers.php';require_once '../pedidos/helpers.php';
$secret=getenv('BCMR_WEBHOOK_SECRET')?:'';if($secret==='')jsonResponse(false,'Webhook genérico não configurado.',[],503);$raw=file_get_contents('php://input')?:'';$sig=$_SERVER['HTTP_X_BCMR_SIGNATURE']??'';$expected=hash_hmac('sha256',$raw,$secret);if(!$sig||!hash_equals($expected,$sig))jsonResponse(false,'Assinatura inválida.',[],401);$in=json_decode($raw,true)?:[];$external=substr(trim($in['identificador_externo']??''),0,190);$status=strtoupper(trim($in['status']??''));$valor=(float)($in['valor']??0);if($external===''||!in_array($status,['APROVADO','RECUSADO','CANCELADO','ESTORNADO'],true))jsonResponse(false,'Payload inválido.',[],400);$s=$conn->prepare('SELECT * FROM pagamentos WHERE identificador_externo=? OR idempotency_key=? LIMIT 1');$s->bind_param('ss',$external,$external);$s->execute();$pg=$s->get_result()->fetch_assoc();if(!$pg)jsonResponse(false,'Pagamento não encontrado.',[],404);if(abs((float)$pg['valor']-$valor)>0.01)jsonResponse(false,'Valor divergente.',[],409);if($pg['status']===$status)jsonResponse(true,'Evento já processado.');
$conn->begin_transaction();try{$paid=$status==='APROVADO'?'NOW()':'NULL';$payload=json_encode($in,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$x=$conn->prepare("UPDATE pagamentos SET status=?,identificador_externo=?,payload_gateway=?,pago_em=$paid WHERE id=?");$pgid=(int)$pg['id'];$x->bind_param('sssi',$status,$external,$payload,$pgid);$x->execute();if(!empty($pg['pedido_id'])){$pedido=(int)$pg['pedido_id'];if($status==='APROVADO')confirmarReservaPedido($conn,$pedido);elseif(in_array($status,['RECUSADO','CANCELADO'],true)){liberarReservaPedido($conn,$pedido,'Webhook '.$status);$x=$conn->prepare("UPDATE pedidos SET status='CANCELADO' WHERE id=?");$x->bind_param('i',$pedido);$x->execute();}}
criarEventoENotificar($conn,1,0,'Pagamento '.$status,'Pagamento #'.$pgid.' confirmado pelo gateway.',$status==='APROVADO'?'ATENCAO':'INFORMATIVO','PAGAMENTO',$pgid,'PAGAMENTO_WEBHOOK:'.$pgid.':'.$status,'PAGAMENTOS','PAGAMENTO_'.$status);enfileirarSheets($conn,1,'PAGAMENTO','PAGAMENTO',$pgid);if(!empty($pg['pedido_id']))enfileirarSheets($conn,1,'PEDIDO','PEDIDO',(int)$pg['pedido_id']);$conn->commit();jsonResponse(true,'Webhook processado.');}catch(Throwable $e){$conn->rollback();jsonResponse(false,'Falha no processamento.',[],500);}
